/**
 * Jinx Plague Doctor + Spy: rules tests.
 *
 * Wiki: https://wiki.bloodontheclocktower.com/Plague_Doctor
 * Wiki: https://wiki.bloodontheclocktower.com/Spy
 * (the wiki has no jinx page; each character's page lists the jinx under "Related Jinxes")
 *
 * Generated by `npm run scaffold:rules-tests`. Replace the `it.todo` with tests of the rule
 * the jinx imposes, where the engine can check it (for example a setup warning when only one
 * of the two may be in play). Paraphrase, never copy wiki prose.
 */
import { describe, expect, it } from 'vitest';
import type { Script } from '#lib/core/data/index.ts';
import { castWith, codes, run } from '#lib/core/model/fixtures.test-support.ts';
import { scriptCharacterIds } from '#lib/core/model/characters.ts';
import { heldAbilitiesOf } from '#lib/core/rules/gained-abilities.ts';
import { givenInstead, jinxRulesBetween } from '#lib/core/rules/jinxes.ts';
import { findJinx, jinxesAmong } from '#lib/core/data/index.ts';
import { committedGameData } from '#lib/core/testing/committed-data.ts';

describe('Plague Doctor + Spy jinx', () => {
	const data = committedGameData();
	const jinx = findJinx(data.jinxes, 'plaguedoctor', 'spy');

	it('is in jinxes.json between two official characters', () => {
		expect(data.byId.get('plaguedoctor')?.name).toBe('Plague Doctor');
		expect(data.byId.get('spy')?.name).toBe('Spy');
		expect(jinx).toBeDefined();
		expect(jinx?.reason).not.toBe('');
	});

	it('applies only when both characters are on the script', () => {
		expect(jinxesAmong(data.jinxes, ['plaguedoctor', 'spy'])).toContain(jinx);
		expect(jinxesAmong(data.jinxes, ['plaguedoctor'])).not.toContain(jinx);
		expect(jinxesAmong(data.jinxes, ['spy'])).not.toContain(jinx);
	});

	// Both pages' Related Jinxes: instead of the Storyteller gaining the Spy ability when the
	// Plague Doctor dies, a Minion gains it and is told so.
	describe('a Minion gains the Spy ability instead of the Storyteller', () => {
		const script: Script = {
			meta: { name: 'Jinxed' },
			entries: ['plaguedoctor', 'imp', 'spy', 'poisoner', 'chef', 'empath', 'monk', 'saint'].map(
				(id) => ({
					kind: 'official' as const,
					id
				})
			)
		};
		const ids = scriptCharacterIds(script);
		const cast = castWith({ script });

		it("is data in the Plague Doctor's rules", () => {
			expect(jinxRulesBetween('plaguedoctor', 'spy')).toEqual({ givenInstead: 'a-minion' });
			expect(givenInstead('plaguedoctor', 'spy', ids)).toBe('a-minion');
			expect(givenInstead('plaguedoctor', 'spy', ['plaguedoctor', 'imp'])).toBeUndefined();
			expect(givenInstead('plaguedoctor', 'poisoner', ids)).toBeUndefined();
		});

		it('warns when the Storyteller takes it anyway', () => {
			const { session, ctx } = cast(['plaguedoctor', 'imp', 'poisoner', 'chef', 'empath']);
			const taken = run(session, ctx, {
				type: 'SetStorytellerAbility',
				via: 'plaguedoctor',
				characterId: 'spy'
			});
			expect(codes(taken)).toEqual(['jinxed-ability']);
			expect(taken.game.storytellerAbilities).toEqual([
				{ characterId: 'spy', via: 'plaguedoctor' }
			]);
		});

		it('a Minion holds it and has it; a good player given it only warns', () => {
			const { session, ctx, seats } = cast(['plaguedoctor', 'imp', 'poisoner', 'chef', 'empath']);
			const given = run(session, ctx, {
				type: 'SetHeldAbility',
				seatId: seats[2],
				via: 'plaguedoctor',
				characterId: 'spy'
			});
			expect(codes(given)).toEqual([]);
			expect(heldAbilitiesOf(given.game, seats[2], ctx.characters)).toEqual([
				{ characterId: 'spy', via: 'plaguedoctor', works: true }
			]);
			const good = run(session, ctx, {
				type: 'SetHeldAbility',
				seatId: seats[3],
				via: 'plaguedoctor',
				characterId: 'spy'
			});
			expect(codes(good)).toEqual(['not-minion']);
			expect(heldAbilitiesOf(good.game, seats[3], ctx.characters)[0]?.works).toBe(false);
		});
	});
});
